interface SchemaResourcePlan {
  resources: object[];
  resourceIds: string[];
  syntheticIds: string[];
  relativeSchemaBase: URL;
  attempt: number;
}

function collectAbsoluteSchemaOrigins(schema: Draft7Schema, origins: Set<string>): void {
  if (typeof schema === "boolean") return;
