        "mediaType": "text/markdown; charset=utf-8",
        "path": "SKILL.md",
        "sha256": "8b90e957ed89306e609f6714cc47c9f05eee8f8ea9071237734e284e2d95f228"
      },
      {
        "byteSize": 655,
        "mediaType": "application/json",
