query = '''query($cursor: String) {
  repository(owner: "21nCo", name: "super-functions") {
    pullRequest(number: 204) {
      headRefOid
      state
      reviewThreads(first: 100, after: $cursor) {
        nodes { id isResolved path line originalLine comments(first: 100) {
          nodes { id body author { login } createdAt outdated url diffHunk originalLine line }
          pageInfo { hasNextPage endCursor }
        } }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
}'''
comments_query = '''query($thread: ID!, $cursor: String) {
  node(id: $thread) {
    ... on PullRequestReviewThread {
      comments(first: 100, after: $cursor) {
        nodes { id body author { login } createdAt outdated url diffHunk originalLine line }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
}'''
threads = []
cursor = None
page_count = 0
nested_pages = 0
