    head_values.append(data['headRefOid'])
    page = data['reviewThreads']
    page_count += 1
    for thread in page['nodes']:
        comments = thread['comments']
        while comments['pageInfo']['hasNextPage']:
            nested_pages += 1
            extra = gh('api', 'graphql', '-f', 'query=' + comments_query, '-f', 'thread=' + thread['id'], '-f', 'cursor=' + comments['pageInfo']['endCursor'])['data']['node']['comments']
            thread['comments']['nodes'] += extra['nodes']
            comments = extra
        thread['comments']['pageInfo'] = comments['pageInfo']
        threads.append(thread)
    if not page['pageInfo']['hasNextPage']: break
    cursor = page['pageInfo']['endCursor']

view = gh('pr', 'view', '204', '--repo', '21nCo/super-functions', '--json', 'headRefOid,state,reviews,comments,updatedAt,url,statusCheckRollup')
raw = gh('api', '--paginate', '--slurp', 'repos/21nCo/super-functions/pulls/204/comments?per_page=100')
if isinstance(raw, list) and raw and isinstance(raw[0], list):
    raw = [item for page in raw for item in page]
output = {
  'capturedAt': datetime.now(timezone.utc).isoformat(),
  'threadPageCount': page_count,
  'nestedExtraPageCount': nested_pages,
  'headsDuringCollection': head_values,
  'headStable': len(set(head_values + [view['headRefOid']])) == 1,
  'threads': threads,
  'view': view,
  'rawInlineComments': raw,
}
path = '/tmp/pr204-review-snapshot-round11.json'
with open(path, 'w') as f: json.dump(output, f, indent=2)
checks = view.get('statusCheckRollup') or []
print(json.dumps({
  'path': path,
  'head': view['headRefOid'],
  'state': view['state'],
  'headStable': output['headStable'],
  'threadPages': page_count,
  'nestedExtraPages': nested_pages,
  'threads': len(threads),
  'unresolved': sum(not t['isResolved'] for t in threads),
  'reviews': len(view['reviews']),
  'issueComments': len(view['comments']),
  'rawInlineComments': len(raw),
  'checks': [{'name': c.get('name') or c.get('context'), 'status': c.get('status') or c.get('state'), 'conclusion': c.get('conclusion')} for c in checks],
}, indent=2))
