  let attempt = 0;
  while (true) {
    const plan = planSchemaResources(schemas, attempt);
    try {
      const lookup = buildCfWorkerLookup(plan.resources);
      assertCfWorkerReferencesResolved(lookup);
      return { plan, lookup };
    } catch (error) {
      if (!isSyntheticIdCollision(error, plan.syntheticIds)) throw error;
      attempt += 1;
    }
